|- INJP =
   (\_17554 _17555 n a.
        if NUMLEFT n then _17554 (NUMRIGHT n) a else _17555 (NUMRIGHT n) a)

|- nadd_inv =
   (\_23562.
        if nadd_eq _23562 (nadd_of_num 0)
        then nadd_of_num 0
        else mk_nadd (nadd_rinv _23562))

|- pastecart =
   (\_95085 _95086.
        lambda i.
            if i <= dimindex (:M)
            then _95085$i
            else _95086$(i - dimindex (:M)))

|- dropout =
   (\_337744 _337745.
        lambda i.
            if i < _337744 /\ i <= dimindex (:M)
            then _337745$i
            else if i + 1 <= dimindex (:M) then _337745$(i + 1) else &0)

|- forall s t.
       s <=_c t
       ==> {u | u SUBSET s /\ FINITE u} <=_c {v | v SUBSET t /\ FINITE v}

|- forall s t.
       s <=_c t /\ (forall f s. P s ==> Q (IMAGE f s))
       ==> {u | u SUBSET s /\ P u} <=_c {v | v SUBSET t /\ Q v}

|- forall s t.
       FINITE s /\ FINITE t /\ s INTER t = {}
       ==> CARD (s UNION t) = CARD s + CARD t

|- forall k s.
       cartesian_product k s =
       {f | forall i. f i IN (if i IN k then s i else {ARB})}

|- forall k s.
       cartesian_product k s =
       {RESTRICTION k f | f | forall i. i IN k ==> f i IN s i}

|- forall a b c d.
       collinear {a, b, c} /\ collinear {b, c, d} /\ ~(b = c)
       ==> collinear {a, b, d}

|- forall A.
       columns A =
       IMAGE (\x. A ** x) {basis i | 1 <= i /\ i <= dimindex (:M)}

|- forall f A.
       (forall x y. f x = f y ==> x = y) /\ COUNTABLE A
       ==> COUNTABLE {x | f x IN A}

|- forall f A s.
       (forall x y. x IN s /\ y IN s /\ f x = f y ==> x = y) /\ COUNTABLE A
       ==> COUNTABLE {x | x IN s /\ f x IN A}

|- forall f s t.
       COUNTABLE s /\ (forall x. x IN s ==> COUNTABLE (t x))
       ==> COUNTABLE {f x y | x IN s /\ y IN t x}

|- forall f g.
       INTERS f CROSS INTERS g =
       (if f = {}
        then INTERS {(:A) CROSS t | t IN g}
        else if g = {}
             then INTERS {s CROSS (:B) | s IN f}
             else INTERS {s CROSS t | s IN f /\ t IN g})

|- forall P s t.
       {x | x IN s DIFF t /\ P x} =
       {x | x IN s /\ P x} DIFF {x | x IN t /\ P x}

|- forall P.
       (forall i. 1 <= i /\ i <= dimindex (:N) ==> FINITE {x | P i x})
       ==> FINITE {v | forall i. 1 <= i /\ i <= dimindex (:N) ==> P i (v$i)}

|- forall f t.
       FINITE t /\ (forall y. y IN t ==> FINITE {x | f x = y})
       ==> FINITE {x | f x IN t}

|- forall f s t.
       FINITE t /\ (forall y. y IN t ==> FINITE {x | x IN s /\ f x = y})
       ==> FINITE {x | x IN s /\ f x IN t}

|- forall f A.
       (forall x y. f x = f y ==> x = y) /\ FINITE A
       ==> FINITE {x | f x IN A}

|- forall f A s.
       (forall x y. x IN s /\ y IN s /\ f x = f y ==> x = y) /\ FINITE A
       ==> FINITE {x | x IN s /\ f x IN A}

|- forall f s t.
       FINITE s /\ (forall x. x IN s ==> FINITE (t x))
       ==> FINITE {f x y | x IN s /\ y IN t x}

|- forall s t k.
       FINITE s /\ FINITE t
       ==> FINITE {f | IMAGE f s SUBSET t /\ {x | ~(f x = k x)} SUBSET s}

|- forall P p s.
       (forall x. x IN s ==> p x) /\ P {x | p x}
       ==> (forall x. x IN P hull s ==> p x)

|- forall k s i.
       IMAGE (\x. x i) (cartesian_product k s) =
       (if cartesian_product k s = {}
        then {}
        else if i IN k then s i else {ARB})

|- forall s t.
       independent s /\ independent t /\ span s INTER span t SUBSET {vec 0}
       ==> independent (s UNION t)

|- forall f s.
       INTERS {UNIONS (f x) | x IN s} =
       UNIONS {INTERS {g x | x IN s} | g | forall x. x IN s ==> g x IN f x}

|- forall P s t.
       {x | x IN s INTER t /\ P x} =
       {x | x IN s /\ P x} INTER {x | x IN t /\ P x}

|- forall dom neut op (<<=) k f.
       iterato dom neut op (<<=) k f =
       (if FINITE {i | i IN k /\ f i IN dom DIFF {neut}}
        then iterato dom neut op (<<=) {i | i IN k /\ f i IN dom DIFF {neut}}
             f
        else neut)

|- forall f g s.
       FINITE {x | x IN s /\ ~(f x = 0)} /\ FINITE {x | x IN s /\ ~(g x = 0)}
       ==> nsum s (\x. f x + g x) = nsum s f + nsum s g

|- forall f g s.
       (forall x. x IN s ==> f x <= g x) /\ FINITE {x | x IN s /\ ~(g x = 0)}
       ==> nsum s f <= nsum s g

|- forall s t.
       (forall a b. a IN s /\ b IN t ==> orthogonal a b)
       ==> s INTER t SUBSET {vec 0}

|- forall x y z.
       ~(x = vec 0) /\ orthogonal x y /\ orthogonal x z
       ==> collinear {vec 0, y, z}

|- forall f g.
       INTERS f PCROSS INTERS g =
       (if f = {}
        then INTERS {(:A^M) PCROSS t | t IN g}
        else if g = {}
             then INTERS {s PCROSS (:A^N) | s IN f}
             else INTERS {s PCROSS t | s IN f /\ t IN g})

|- forall u v.
       pairwise DISJOINT v /\ u PSUBSET v DELETE {}
       ==> UNIONS u PSUBSET UNIONS v

|- forall p.
       span p =
       {y | exists s u. FINITE s /\ s SUBSET p /\ vsum s (\v. u v % v) = y}

|- forall (a:real^?242303).
       (span:(real^?242303->bool)->real^?242303->bool) {(a:real^?242303)} =
       {u % (a:real^?242303) | u IN (:real)}

|- forall s t u.
       {w + z | w IN {x + y | x IN s /\ y IN t} /\ z IN u} =
       {x + v | x IN s /\ v IN {y + z | y IN t /\ z IN u}}

|- forall f s.
       UNIONS {INTERS (f x) | x IN s} =
       INTERS {UNIONS {g x | x IN s} | g | forall x. x IN s ==> g x IN f x}

|- forall P s t.
       {x | x IN s UNION t /\ P x} =
       {x | x IN s /\ P x} UNION {x | x IN t /\ P x}

|- forall k s.
       cartesian_product k s =
       {f | EXTENSIONAL k f /\ (forall i. i IN k ==> f i IN s i)}

|- forall k x.
       dropout k x =
       (lambda i.
            if i < k /\ i <= dimindex (:M)
            then x$i
            else if i + 1 <= dimindex (:M) then x$(i + 1) else &0)

|- forall a b.
       interval (a,b) =
       {x | forall i. 1 <= i /\ i <= dimindex (:N) ==> a$i < x$i /\ x$i < b$i}

|- forall f.
       suslin_operation f =
       UNIONS {INTERS {f (list_of_seq s n) | 1 <= n} | s IN (:num->num)}
